woke=False
def control(obs):
    global ph,woke
    h=obs['hitch_deg']
    c=obs['progress']['covered']
    if ph==0:
        if c<14.0:
            ph=1
        else:
            return (-h, 2.0, 53)
    rig=obs['rig']
    hx,hy=rig['hitch']
    rx,ry=rig['trailer_rear']
    L=math.hypot(rx-hx,ry-hy) or 1.0
    ux,uy=(rx-hx)/L,(ry-hy)/L
    gap=9.0
    m=(obs.get('views') or {}).get('left_mirror')
    if m:
        ox,oy=m['origin']
        for b,d in m['walls']:
            px=ox+d*math.cos(math.radians(b))-hx
            py=oy+d*math.sin(math.radians(b))-hy
            al=px*ux+py*uy
            lat=px*uy-py*ux
            if 0.4*L<al<L+2.5 and lat>0:
                gap=min(gap,lat-1.275)
    s=1.5*h
    s=max(-42.0,min(42.0,s))
    if gap<0.6 and c>12:
        if not woke:
            woke=True
            wake('gap %.2f at %.1f'%(gap,c))
        return (s,0.0,53)
    return (s,-0.8,53)

